`+e),alert("Copiado al portapapeles")}catch{try{alert(e)}catch{}}}var z=["\u{1F30E} \xC9tica de lo suficiente, no del acumular","\u{1F33F} Parte viva de la comunidad terrenal, no due\xF1a","\u{1F4A7}\u{1F32C}\uFE0F\u{1F525} Aire, agua, suelo, monta\xF1a, \xE1rbol, animal: familia","\u267B\uFE0F Frugal, consciente y regenerativo","\u2764\uFE0F Afectivo, espiritual y comunitario","\u270A No al individualismo, lucro desmedido y mercantilizaci\xF3n de la vida"],T=[{nombre:"K\xFCme Mongen",pueblo:"Pueblo Mapuche",sig:"\u201Cbuen vivir\u201D",ico:"\u{1F30E}",texto:"Conexi\xF3n profunda con la naturaleza, en equilibrio con las fuerzas y seres que la habitan. Armon\xEDa entre el agua, el territorio, la vida personal, familiar y comunitaria, la cultura y las energ\xEDas espirituales. Reconstruir el K\xFCme Mongen es reconstruir una sociedad con dignidad, solidaridad y reciprocidad para todos los pueblos. Es, ante todo, una lucha por amor a la vida."},{nombre:"Sumak Kawsay",pueblo:"Pueblo Kichwa \xB7 Ecuador",sig:"\u201Cvida plena en armon\xEDa\u201D",ico:"\u{1F30E}",texto:"Gu\xEDa las relaciones dentro del Ayllu (comunidad) y entre la comunidad y la naturaleza. Vivir en equilibrio con los r\xEDos, los bosques, las monta\xF1as, los esp\xEDritus protectores y los dioses: todo est\xE1 interconectado y merece respeto."},{nombre:"\xD1ande Reko",pueblo:"Pueblo Guaran\xED",sig:"\u201Cnuestro modo de ser\u201D",ico:"\u{1F30E}",texto:"Libertad, alegr\xEDa comunitaria, reciprocidad y convite. Todo orientado a la b\xFAsqueda de la Tierra Sin Mal: un mundo justo, en paz y en plenitud."},{nombre:"Vivir Bien",pueblo:"Pueblo Kolla \xB7 Argentina",sig:"crecer con la naturaleza",ico:"\u{1F30E}",texto:"Crecer con la naturaleza, no contra ella. Como dice el sabio Huanacuni: \u201CEl ser humano es tierra que anda\u201D. La vida florece solo cuando se respeta ese v\xEDnculo sagrado."},{nombre:"Shiir Waras",pueblo:"Pueblo Shuar \xB7 Ecuador",sig:"\u201Cbuen vivir\u201D",ico:"\u{1F30E}",texto:"Paz dom\xE9stica y vida armoniosa, en equilibrio con la familia, la comunidad y la naturaleza. Bienestar integral, tejido en el d\xEDa a d\xEDa."},{nombre:"Balu Wala",pueblo:"Pueblo Guna \xB7 Panam\xE1 y Colombia",sig:"\u201C\xE1rbol de sal\u201D",ico:"\u{1F30E}",texto:"Eje filos\xF3fico de la existencia guna: relaci\xF3n indisoluble entre humanidad, naturaleza y universo, fundada en el respeto, la equidad y la armon\xEDa. Gu\xEDa las relaciones pol\xEDticas, econ\xF3micas y sociales, y fortalece la producci\xF3n comunitaria y la calidad de vida colectiva, desde la memoria y el presente comunitario."},{nombre:"Suma Qama\xF1a",pueblo:"Pueblos Aymara y Quechua \xB7 Andes",sig:"\u201Cvivir bien\u201D",ico:"\u{1F30E}",texto:"Paradigma andino: relacionalidad, complementariedad, ciclicidad, correspondencia y conciencia natural. La vida es un todo org\xE1nico donde dialogan Jaqi (seres humanos), Wak\u2019a (divinidades) y Sallqa (naturaleza silvestre). Con-vivir en armon\xEDa con la Tierra, el mundo espiritual y las futuras generaciones."}],V=[{ico:"\u{1F4A7}",t:"Cuida el agua",d:"Ducha corta, repara goteos, riega al atardecer. El agua no se gasta: se devuelve limpia."},{ico:"\u267B\uFE0F",t:"Reutiliza y recicla",d:"Separa vidrio, pl\xE1stico, papel y aceite. Lleva al punto limpio; lo org\xE1nico al compost."},{ico:"\u{1F96C}",t:"Consume local y de estaci\xF3n",d:"Feria de Penco, trueque con vecinos, huerta propia. Menos envase, m\xE1s territorio."},{ico:"\u{1F91D}",t:"Haz minga",d:"Una mano lava la otra: ayuda en cosechas, techos o limpieza de quebrada. An\xF3tala y convoca."},{ico:"\u{1F331}",t:"Planta nativo",d:"Peumo, quillay, boldo, chilco en Pukem con lluvia. En el cerro: foto antes que muestra."},{ico:"\u{1F525}",t:"Energ\xEDa justa",d:"Le\xF1a seca, olla tapada, luz solo donde est\xE1s. Lo suficiente abriga igual."},{ico:"\u{1F64F}",t:"Agradece y pide permiso",d:"Llellipun antes de cortar, gratitud despu\xE9s de recibir. Devuelve algo siempre."},{ico:"\u{1F5E3}\uFE0F",t:"Transmite",d:"Ense\xF1a un oficio, graba a tus abuelos, cuenta un epew. La memoria tambi\xE9n se siembra."}],P=["\u{1F4A7} Agua","\u267B\uFE0F Residuos","\u{1F96C} Consumo","\u{1F91D} Comunidad","\u{1F331} Territorio","\u{1F525} Energ\xEDa","\u{1F64F} Esp\xEDritu"];function b(){var a=O("buenVivir",{compromisos:[]});if(!a||!Array.isArray(a.compromisos))try{var e=userData();return e.buenVivir={compromisos:[]},e.buenVivir}catch{return{compromisos:[]}}return a}function D(){var a=[];try{a=b().compromisos||[]}catch{}var e=a.filter(function(t){return t.hecho}).length;return{total:a.length,hechas:e}}function E(a){if(!a.length)return"\u{1F30E} Mis compromisos del Buen Vivir \u2014 a\xFAn sin registros";var e="\u{1F30E} Mis compromisos del Buen Vivir \xB7 "+a.length+`

